function stable(f,seconds=10){const before=f.snapshot(),markup=f.render(),read=f.observation(),frames=f.frames;f.tick(seconds);assert.equal(f.snapshot(),before,'held state exact');assert.equal(f.render(),markup,'held geometry exact');assert.deepEqual(f.observation(),read,'held observation exact');assert.equal(f.frames,frames,'held state does not draw');assert.equal(f.pending,0,'held state parks RAF');}
