function vendStart(f,i=0,coins=1){for(let j=0;j<coins;j++){f.action('token');f.finish();}f.action('faultNext');f.action('choose',{i:String(i)});}
function inventory(f,total=9){const held=f.s.delivered===null?0:1;assert.equal(f.s.stock.reduce((a,b)=>a+b,0)+held+f.s.collected,total,'can conservation');if(!['restocking'].includes(f.s.phase)){const cans=f.cans();assert.equal(cans.length,f.s.stock.reduce((a,b)=>a+b,0)+held,'render exactly available stock plus one reserved can');assert.equal(new Set(cans.map(c=>[c.x,c.y,c.z].join('/'))).size,cans.length,'no overlapping duplicate can at identical pose');}}
function vendingTests(){
 test('vending fault is opt-in, survives unsuccessful selection, and normal flow stays unchanged',()=>{const f=fixture('vending',{setup:true});assert.equal(f.s.jamNext,false);assert.equal(f.s.reservedCoin,0);assert.equal(f.ui.observation.panel.open,false);assert.match(f.cfg.observation.intro,/传感器没有展开模拟/);f.action('faultNext');f.action('choose',{i:'1'});assert.equal(f.s.jamNext,true);assert.equal(f.s.delivered,null);f.action('faultNext');f.action('token');f.finish();f.action('choose',{i:'1'});f.finish();assert.equal(f.s.phase,'ready');assert.equal(f.s.reservedCoin,1);f.action('collect');f.finish();assert.equal(f.s.collected,1);assert.equal(f.s.reservedCoin,0);inventory(f);stable(f);});
 test('vending three shelf heights stop the actual single can exactly at release .28 and park RAF',()=>{for(const i of [0,1,2]){const f=fixture('vending',{setup:true});vendStart(f,i,3);assert.equal(f.s.tokens,2);assert.equal(f.s.reservedCoin,1);assert.equal(f.s.stock[i],2);inventory(f);let previous=f.actualCan(),trace=[];while(f.pending){f.frame();inventory(f);const current=f.actualCan();assert(current.x>=previous.x-1e-9);near(current.y,32);near(current.z,33+15.5*i);assert(Math.abs(current.x-previous.x)<=2*5.8/.532*.04+1e-9,'release is continuous across frames');previous=current;trace.push({phase:f.s.phase,drop:f.s.drop,...current});}assert.equal(f.s.phase,'jammed');near(f.s.drop,.28);near(previous.x,41.1);near(previous.z,33+15.5*i);assert.equal(f.cfg.progress(f.s),null);stable(f,30);evidence.push({vending:'jam',i,trace});for(const action of ['token','choose','collect','refill','faultNext','continue']){const before=f.snapshot();f.action(action,{i:'2'});f.finish();assert.equal(f.snapshot(),before,'blocked while jammed '+action);}}});
 test('vending recovery reverses the same path continuously, retains one reservation, then continues without double charge',()=>{for(const i of [0,1,2]){const f=fixture('vending',{setup:true});vendStart(f,i,2);f.finish();const jam=f.actualCan();f.action('recover');assert.deepEqual(f.actualCan(),jam,'recovery starts from exact jam pose');let previous=jam,trace=[];while(f.pending){f.frame();inventory(f);const p=f.actualCan();assert(p.x<=previous.x+1e-9);near(p.y,jam.y);near(p.z,jam.z);assert(Math.abs(p.x-previous.x)<=2*5.8/.75*.04+1e-9,'recovery never teleports');previous=p;trace.push({phase:f.s.phase,drop:f.s.drop,...p});}assert.equal(f.s.phase,'recovered');near(f.s.drop,0);near(previous.x,35.3);assert.equal(f.s.tokens,1);assert.equal(f.s.reservedCoin,1);assert.equal(f.s.stock[i],2);stable(f);const before=clone({tokens:f.s.tokens,stock:f.s.stock,reserved:f.s.reservedCoin});f.action('continue');assert.deepEqual(f.actualCan(),previous,'continue begins at exact recovered pose');assert.deepEqual(clone({tokens:f.s.tokens,stock:f.s.stock,reserved:f.s.reservedCoin}),before);f.finish();assert.equal(f.s.phase,'ready');inventory(f);f.action('collect');f.action('collect');f.finish();assert.equal(f.s.phase,'idle');assert.equal(f.s.collected,1);assert.equal(f.s.tokens,1);assert.equal(f.s.reservedCoin,0);inventory(f);f.action('refund');f.finish();assert.equal(f.s.refund,1);assert.equal(f.s.tokens,0);evidence.push({vending:'recover',i,trace});}});
 test('vending refund/reset chains return the real can before refunding all held coins once',()=>{for(const afterRecovery of [false,true])for(const reset of [false,true])for(const coins of [1,3]){const f=fixture('vending',{setup:true});vendStart(f,2,coins);f.finish();if(afterRecovery){f.action('recover');f.finish();}const pose=f.actualCan(),allCansBefore=f.cans().map(c=>JSON.stringify(c)).sort();f.action(reset?'reset':'refund');if(afterRecovery)assert.deepEqual(f.cans().map(c=>JSON.stringify(c)).sort(),allCansBefore,'return-to-stock is exact geometry substitution, not ghost or jump');if(!afterRecovery)assert.deepEqual(f.actualCan(),pose);let seenReturning=false,returnedInventory=false;for(let frame=0;f.pending&&frame<200;frame++){f.frame();if(f.s.phase==='returning'){seenReturning=true;assert.equal(f.s.delivered,null);assert.equal(f.s.stock[2],3);returnedInventory=true;assert.equal(f.s.refund,coins);assert.equal(f.s.reservedCoin,1);assert.equal(f.s.tokens,coins-1);}else if(f.s.phase==='recovering'){assert.equal(f.s.stock[2],2);assert.equal(f.s.delivered,2);}for(const action of ['recover','refund','reset','continue','choose','collect']){if(f.s.phase==='idle')break;const state=f.snapshot();f.action(action,{i:'0'});assert.equal(f.snapshot(),state,'repeated '+action+' during '+f.s.phase);}inventory(f);}assert.equal(f.pending,0);assert(seenReturning&&returnedInventory);assert.equal(f.s.phase,'idle');assert.equal(f.s.tokens,0);assert.equal(f.s.reservedCoin,0);assert.equal(f.s.delivered,null);assert.equal(f.s.stock[2],3);assert.equal(f.s.collected,0);stable(f);f.action('refund');f.finish();assert.equal(f.s.tokens,0);}});
 test('vending early reset rewinds only its partial release and retiring/restarting drivers cannot revive ghosts',()=>{for(const at of [0,.04,.24,.48]){const f=fixture('vending',{setup:true});vendStart(f,0,2);f.tick(at);const before=f.actualCan();assert.equal(f.s.phase,'drop');f.action('reset');if(at>0)assert.deepEqual(f.actualCan(),before,'partial reset exact initial pose');f.finish();assert.equal(f.s.phase,'idle');assert.equal(f.s.delivered,null);assert.equal(f.s.stock.reduce((a,b)=>a+b,0),9);assert.equal(f.s.tokens,0);assert.equal(f.s.reservedCoin,0);stable(f);f.action('token');f.finish();f.action('choose',{i:'1'});f.finish();f.action('collect');f.finish();assert.equal(f.s.collected,1);inventory(f);}const f=fixture('vending',{setup:true});for(let n=0;n<12;n++){vendStart(f,n%3,1);f.finish();f.action('recover');f.tick(.2);const before=f.snapshot();f.action('reset');assert.equal(f.snapshot(),before,'reset cannot interrupt ongoing return');f.finish();f.action('refund');f.finish();inventory(f);assert.equal(f.s.tokens,0);assert.equal(f.s.reservedCoin,0);}stable(f);});
 test('vending same state drives quarter-speed jam and recovery, hidden pause, scene disposal, and fresh entry',()=>{const fast=fixture('vending',{setup:true}),slow=fixture('vending',{setup:true});vendStart(fast,1,1);vendStart(slow,1,1);slow.ui.simulationRate=.25;for(let n=0;n<10;n++){fast.frame();for(let j=0;j<4;j++)slow.frame();near(fast.s.drop,slow.s.drop);assert.deepEqual(fast.actualCan(),slow.actualCan());}fast.finish();slow.finish();near(fast.s.drop,slow.s.drop);fast.action('recover');slow.action('recover');for(let n=0;n<10;n++){fast.frame();for(let j=0;j<4;j++)slow.frame();near(fast.s.drop,slow.s.drop);const a=fast.actualCan(),b=slow.actualCan();near(a.x,b.x);near(a.y,b.y);near(a.z,b.z);}fast.document.hidden=true;fast.document.emit('visibilitychange');const held=fast.snapshot();fast.tick(20);assert.equal(fast.snapshot(),held);assert.equal(fast.pending,0);fast.document.hidden=false;fast.document.emit('visibilitychange');fast.finish();assert.equal(fast.s.phase,'recovered');fast.action('continue');fast.tick(.2);fast.c.location.hash='#camera';fast.event('hashchange');const stopped=fast.snapshot();fast.ui.dispose();assert.equal(fast.snapshot(),stopped,'repeat dispose is idempotent');fast.finish();assert.equal(fast.snapshot(),stopped,'disposed scene cannot progress stale transaction');assert.equal(fast.pending,0);const fresh=fixture('vending',{setup:true});assert.equal(fresh.s.jamNext,false);assert.equal(fresh.s.phase,'idle');assert.equal(fresh.s.delivered,null);assert.equal(fresh.s.tokens,0);});
 test('vending optional controls accurately lock and offer recovery then continue/refund',()=>{const f=fixture('vending',{setup:true}),panel=f.ui.observation.panel;f.toggle(panel,true);f.finish();const box=panel.querySelector('.vending-fault'),toggle=box.querySelector('input'),buttons=box.querySelectorAll('button');const by=text=>buttons.find(b=>b.textContent===text);assert.equal(toggle.checked,false);assert.equal(toggle.disabled,false);assert(buttons.every(b=>b.disabled));toggle.onchange();f.finish();assert.equal(f.s.jamNext,true);f.action('token');f.finish();f.action('choose',{i:'0'});f.finish();assert.equal(toggle.disabled,true);assert.equal(by('检修复位').disabled,false);assert.equal(by('继续出货').disabled,true);assert.equal(by('取消并退币').disabled,false);by('检修复位').click();f.tick(.2);assert(buttons.every(b=>b.disabled));f.finish();assert.equal(by('继续出货').disabled,false);assert.equal(by('取消并退币').disabled,false);assert.equal(by('检修复位').disabled,true);by('取消并退币').click();f.finish();assert.equal(toggle.disabled,false);assert(buttons.every(b=>b.disabled));assert.equal(f.s.tokens,0);});
 test('vending raster sources expose jam, reverse-middle, recovered and continuation states',()=>{const f=fixture('vending',{setup:true}),dir=path.join(root,'qa/review-process-visuals');vendStart(f,1,2);f.tick(.28);f.svgSnapshot(path.join(dir,'vending-release-mid.svg'));f.finish();f.svgSnapshot(path.join(dir,'vending-jammed.svg'));f.action('recover');f.tick(.36);f.svgSnapshot(path.join(dir,'vending-reverse-mid.svg'));f.finish();f.svgSnapshot(path.join(dir,'vending-recovered.svg'));f.action('continue');f.tick(1);f.svgSnapshot(path.join(dir,'vending-resumed-fall.svg'));f.finish();f.svgSnapshot(path.join(dir,'vending-ready.svg'));});
}
function vendingBoundarySources(){
 const f=fixture('vending',{setup:true}),dir=path.join(root,'qa/review-process-visuals/boundary-fixed');fs.mkdirSync(dir,{recursive:true});vendStart(f,1,1);f.finish();const jam=clone(f.s);f.action('recover');f.finish();const recovered=clone(f.s);f.action('refund');const refund=clone(f.s);Object.assign(f.s,recovered);f.action('continue');const continued=clone(f.s);
 const states={nearzero:{...recovered,phase:'recovering',drop:1e-10},recovered,continued,refund,releasebefore:{...jam,phase:'drop',drop:.28-1e-10},releaseafter:{...jam,phase:'drop',drop:.28+1e-10}};
 for(const yaw of [45,315])for(const pitch of [6,35,78])for(const[label,state]of Object.entries(states)){Object.assign(f.s,state);const file=path.join(dir,`${label}-${yaw}-${pitch}.svg`);f.svgSnapshot(file,yaw,pitch);const full=fs.readFileSync(file,'utf8'),header=full.slice(0,full.indexOf('>')+1);const layers=f.cfg.scene.layers.filter(p=>['window','deliveryInside'].includes(p.key)).map(p=>p.svg).join('');fs.writeFileSync(file,header+'<rect width="100%" height="100%" fill="#faf8f2"/>'+layers+'</svg>');}
 for(const yaw of [45,315])for(const pitch of [6,35,78]){Object.assign(f.s,{...jam,phase:'recovering',drop:.14});f.svgSnapshot(path.join(dir,`main-mid-${yaw}-${pitch}.svg`),yaw,pitch);Object.assign(f.s,recovered);f.svgSnapshot(path.join(dir,`main-rest-${yaw}-${pitch}.svg`),yaw,pitch);}
 for(const yaw of [135,225]){Object.assign(f.s,jam);f.svgSnapshot(path.join(dir,`main-rear-${yaw}.svg`),yaw,35);}
 for(const yaw of [45,315])for(const drop of [0,.07,.14,.21,.28]){Object.assign(f.s,{...jam,phase:'recovering',drop});f.svgSnapshot(path.join(dir,`path-${yaw}-${drop}.svg`),yaw,35);}
 console.log('Production SVG boundary sources: '+dir+' (raster externally with Inkscape; not browser screenshots).');
}
if(require.main===module){if(process.argv.includes('--boundary-sources'))vendingBoundarySources();else{cameraTests();vendingTests();const report={limits:'Independent production callbacks and real RAF; mocked DOM. SVG raster sources are not browser screenshots. No publication or browser used.',results,evidence};console.log(JSON.stringify(report,null,2));if(results.some(r=>!r.ok))process.exitCode=1;}}
